import { logger } from '../logger'
import { KeyChain } from './keychain'
import { LazyCredential, type ResolvedAuth } from '@servicenow/sdk-api/credentials'
import { refreshAccessToken } from './OAuth'
import { getClientCredentialsToken } from './OAuth/ClientCredentials'
import { getUISessionToken } from './basic-auth'

const SERVICE = 'ServiceNow'
const keyChain = new KeyChain(SERVICE)

export type Credentials = {
    isDefault: boolean
    alias: string
    creds: Creds
}

export type KeyChainStore = {
    [alias: string]: Credentials
}

export type CredentialPreview = {
    isDefault: boolean
    instanceUrl: string
} & (
    | {
          type: 'basic'
          username: string
      }
    | {
          type: 'oauth'
      }
)

export const credentialProvider = async (credentialAlias: string | undefined): Promise<LazyCredential> => {
    const ciCreds = await getCiCredentials()

    const createResolver = (getCredsFunc: () => Promise<Creds> | Creds) => {
        return async (): Promise<ResolvedAuth> => {
            const creds = await getCredsFunc()

            switch (creds.type) {
                case 'basic': {
                    const session = await getUISessionToken(creds)
                    if (!session) {
                        throw new Error('Failed to get user session token for basic auth')
                    }
                    return {
                        type: 'basic',
                        token: session.userToken,
                        cookie: session.cookie,
                    }
                }
                case 'oauth':
                    return {
                        type: 'oauth',
                        token: creds.access_token,
                        expiresAt: creds.expires_at,
                    }
                default:
                    throw new Error(`Unsupported credential type: ${(creds as { type: unknown }).type}`)
            }
        }
    }

    // Authenticated session provided by environment
    if (ciCreds instanceof LazyCredential) {
        return ciCreds
    }

    // Credentials provided but we negotiate our own session
    if (ciCreds) {
        // CI mode - use environment credentials
        return new LazyCredential(
            new URL(ciCreds.instanceUrl),
            createResolver(() => ciCreds)
        )
    }

    // Non-CI mode - use stored credentials
    const storedCredentials = await getStoredCredentials(credentialAlias)

    return new LazyCredential(
        new URL(storedCredentials.creds.instanceUrl),
        createResolver(() => getRefreshedCredentials(storedCredentials))
    )
}

/**
 * Returns environment-based credentials for non-interactive executions.
 *
 * Pre-authenticated sessions (cookies/tokens, no credentials or secrets) are checked
 * first and take precedence over CI credential configs.
 *
 * Supported pre-auth environment variables:
 * - `SN_SDK_INSTANCE_URL` – (required) the target instance URL.
 * - `SN_SDK_SESSION_TOKEN` – a session token for basic auth.
 * - `SN_SDK_SESSION_COOKIE` – an optional session cookie for basic auth.
 * - `SN_SDK_SESSION_BEARER_TOKEN` – a bearer token for OAuth auth (takes precedence).
 *
 * CI credentials are used when `SN_SDK_NODE_ENV` is set to `SN_SDK_CI_INSTALL`.
 *
 * @returns A pre-authenticated {@link LazyCredential}, CI {@link Creds}, or `undefined`
 *          when the environment does not indicate non-interactive auth.
 */
async function getCiCredentials(): Promise<LazyCredential | Creds | undefined> {
    // Pre-authenticated sessions — already authenticated with cookies/tokens, no credentials or secrets.
    const instanceUrl = process.env['SN_SDK_INSTANCE_URL']
    const sessionToken = process.env['SN_SDK_SESSION_TOKEN']
    const sessionCookie = process.env['SN_SDK_SESSION_COOKIE']
    const bearerToken = process.env['SN_SDK_SESSION_BEARER_TOKEN']

    if (sessionToken || bearerToken) {
        if (!instanceUrl) {
            throw new Error('Session auth is missing required environment variable: SN_SDK_INSTANCE_URL')
        }

        logger.info(`Using pre-authenticated session for instance ${instanceUrl}`)

        const resolvedAuth: ResolvedAuth = bearerToken
            ? { type: 'oauth', token: bearerToken }
            : { type: 'basic', token: sessionToken, cookie: sessionCookie }

        return new LazyCredential(new URL(instanceUrl), () => resolvedAuth)
    }

    // CI credentials — trade username/password or client credentials for a session.
    if (process.env['SN_SDK_NODE_ENV'] !== 'SN_SDK_CI_INSTALL') {
        return undefined
    }
    const creds = await getCIAuthConfig()
    logger.info(`Running in CI mode, using instance ${creds.instanceUrl}`)
    return creds
}

async function getRefreshedCredentials(storedCredentials: Credentials): Promise<Creds> {
    const { creds, alias, isDefault } = storedCredentials
    if (creds.type === 'oauth') {
        const newTokens = await refreshAccessToken(creds)
        if (newTokens) {
            const updatedCreds = {
                ...creds,
                ...newTokens,
            } as Creds
            await updateCredentials(alias, updatedCreds, isDefault)
            return updatedCreds
        }
    }
    return creds
}

export async function getCredentials(credentialAlias: string | undefined): Promise<Creds> {
    const ciResult = await getCiCredentials()
    if (ciResult instanceof LazyCredential) {
        throw new Error('Pre-authenticated sessions do not expose raw credentials. Use credentialProvider instead.')
    }
    if (ciResult) {
        return ciResult
    }

    const storedCredentials = await getStoredCredentials(credentialAlias)
    return getRefreshedCredentials(storedCredentials)
}

async function updateCredentials(alias: string, authInfo: Creds, isDefault: boolean): Promise<void> {
    const keyStore = (await getParsedCredentials()) ?? {}

    keyStore[alias] = {
        isDefault,
        alias,
        creds: authInfo,
    }
    await keyChain.setPassword(JSON.stringify(keyStore))
}

async function getStoredCredentials(alias: string | undefined): Promise<Credentials> {
    if (!alias) {
        const defaultCreds = await getDefaultCredentials()
        if (!defaultCreds) {
            throw new Error(
                'Default Credential has not been set, Please provide the credential alias to use or set a default by using "$now-sdk auth --use <alias>" command'
            )
        }
        return defaultCreds
    }

    const keyStore = await getParsedCredentials()
    if (!keyStore || !keyStore[alias]) {
        throw new Error(
            `Could not find stored credentials for alias: ${alias}, Please check the alias provided or save an alias using "$now-sdk auth --add <instance>" command`
        )
    }

    return keyStore[alias]
}

export async function storeCredentials(alias: string, authInfo: Creds, isDefault: boolean): Promise<void> {
    const keyStore = (await getParsedCredentials()) ?? {}

    const defaultCreds = Object.values(keyStore).find((creds) => creds.isDefault)

    keyStore[alias] = {
        isDefault: defaultCreds ? (defaultCreds.alias === alias ? true : isDefault) : true,
        alias,
        creds: authInfo,
    }

    // if new creds are set as default, remove the default flag from the previous default creds
    if (defaultCreds && defaultCreds.alias !== alias && isDefault) {
        keyStore[defaultCreds.alias]!.isDefault = false
    }

    await keyChain.setPassword(JSON.stringify(keyStore))
}

export async function updateDefaultCredential(alias: string) {
    logger.info(`Setting alias ${alias} as default ...`)
    const keyStore = await getParsedCredentials()
    if (!keyStore || !keyStore[alias]) {
        throw new Error(
            `No credentials found for alias ${alias}, Please check the alias provided or save an alias using "$now-sdk auth --add <instance>" command`
        )
    }

    const currentDefaultCreds = await getDefaultCredentials()

    if (currentDefaultCreds?.alias === alias) {
        logger.info(`alias ${alias} is already set as default`)
        return
    }

    if (currentDefaultCreds) {
        keyStore[currentDefaultCreds.alias]!.isDefault = false
    }
    keyStore[alias].isDefault = true

    await keyChain.setPassword(JSON.stringify(keyStore))
    logger.info(`Successfully set alias ${alias} as default`)
}

export async function getDefaultCredentials(): Promise<Credentials | undefined> {
    const keyStore = await getParsedCredentials()

    if (!keyStore) {
        return
    }

    return Object.values(keyStore).find((creds) => creds.isDefault)
}

export async function removeCredentials(alias: string): Promise<void> {
    if (process.env['NODE_ENV'] === 'test') {
        return
    }

    const keyStore = await getParsedCredentials()

    if (alias === 'all') {
        if (!keyStore) {
            return
        }

        logger.info(`Removing all stored credentials ...`)
        await keyChain.deletePassword()
        logger.info(`Successfully removed all stored credentials`)
        return
    }

    logger.info(`Removing credentials for alias: ${alias} ...`)
    if (!keyStore || !keyStore[alias]) {
        logger.info(`No credentials found for alias: ${alias}`)
        return
    }

    delete keyStore[alias]
    await keyChain.setPassword(JSON.stringify(keyStore))
    logger.info(`Successfully removed credentials for alias ${alias}`)
}

export async function fetchCredentials(): Promise<Map<string, CredentialPreview>> {
    if (process.env['NODE_ENV'] === 'test') {
        return new Map()
    }

    const keyStore = await getParsedCredentials()
    const storedCreds: Map<string, CredentialPreview> = new Map()
    if (!keyStore) {
        return storedCreds
    }

    Object.values(keyStore).forEach((creds) => {
        const { alias: storedAlias, credPreview } = getPreviewCredentials(creds)
        storedCreds.set(storedAlias, credPreview)
    })

    return storedCreds
}

function getPreviewCredentials(cred: Credentials): { alias: string; credPreview: CredentialPreview } {
    const { alias, isDefault, creds } = cred

    if (creds.type === 'oauth') {
        return { alias, credPreview: { type: creds.type, instanceUrl: creds.instanceUrl, isDefault } }
    }
    return {
        alias,
        credPreview: { type: creds.type, instanceUrl: creds.instanceUrl, isDefault, username: creds.username },
    }
}

async function getParsedCredentials(): Promise<KeyChainStore | undefined> {
    const currentPassword = await keyChain.getPassword()
    return currentPassword ? (JSON.parse(currentPassword) as KeyChainStore) : undefined
}

const getCIAuthConfig = async (): Promise<Creds> => {
    const authType = process.env['SN_SDK_AUTH_TYPE'] ?? 'basic'

    if (authType === 'basic') {
        const missing = (['SN_SDK_INSTANCE_URL', 'SN_SDK_USER', 'SN_SDK_USER_PWD'] as const).filter(
            (name) => !process.env[name]
        )
        if (missing.length > 0) {
            throw new Error(`CI basic auth is missing required environment variables: ${missing.join(', ')}`)
        }
        return {
            type: 'basic',
            instanceUrl: process.env['SN_SDK_INSTANCE_URL'] as string,
            username: process.env['SN_SDK_USER'] as string,
            password: process.env['SN_SDK_USER_PWD'] as string,
        }
    }

    if (authType === 'oauth') {
        const missing = (
            ['SN_SDK_INSTANCE_URL', 'SN_SDK_OAUTH_CLIENT_ID', 'SN_SDK_OAUTH_CLIENT_SECRET'] as const
        ).filter((name) => !process.env[name])
        if (missing.length > 0) {
            throw new Error(
                `CI OAuth client_credentials is missing required environment variables: ${missing.join(', ')}`
            )
        }
        const instanceUrl = process.env['SN_SDK_INSTANCE_URL'] as string
        const tokens = await getClientCredentialsToken(
            instanceUrl,
            process.env['SN_SDK_OAUTH_CLIENT_ID'] as string,
            process.env['SN_SDK_OAUTH_CLIENT_SECRET'] as string
        )
        return {
            type: 'oauth',
            instanceUrl,
            access_token: tokens.access_token,
            token_type: tokens.token_type,
            refresh_token: tokens.refresh_token,
            expires_at: tokens.expires_at,
        }
    }

    throw new Error(
        `Unsupported value for SN_SDK_AUTH_TYPE: "${process.env['SN_SDK_AUTH_TYPE']}". Expected "basic" or "oauth".`
    )
}

export type BasicCred = {
    instanceUrl: string
    type: 'basic'
    username: string
    password: string
}

export type OAuthCred = {
    instanceUrl: string
    type: 'oauth'
    access_token: string
    token_type: string
    refresh_token: string
    expires_at: number
}

export type Creds = BasicCred | OAuthCred
